package com.aaliyun.leadnews.search.config;
import co.elastic.clients.elasticsearch.ElasticsearchClient;import co.elastic.clients.json.jackson.JacksonJsonpMapper;import co.elastic.clients.transport.rest_client.RestClientTransport;import com.fasterxml.jackson.databind.ObjectMapper;import org.apache.http.HttpHost;import org.elasticsearch.client.RestClient;import org.springframework.beans.factory.annotation.Value;import org.springframework.context.annotation.*;
@Configuration public class ElasticsearchConfiguration{@Bean(destroyMethod="close")RestClient restClient(@Value("${leadnews.search.elasticsearch-url}")String url){return RestClient.builder(HttpHost.create(url)).build();}@Bean ElasticsearchClient client(RestClient rest,ObjectMapper mapper){return new ElasticsearchClient(new RestClientTransport(rest,new JacksonJsonpMapper(mapper)));}}
